import sys; sys.path.insert(0, '.')
from mk2 import *
page(dict(
 slug='telephone',
 title=T('이야기는 전해지며 어떻게 변할까', "How Do Stories Change as They're Retold?"),
 title_tag=T('이야기는 전해지며 어떻게 변할까 · 시뮬라티오 랩', "How Do Stories Change as They're Retold? · Simulatio Lab"),
 desc=T('이야기를 사람에서 사람으로 40번 전하면 무엇이 남고 무엇이 사라질까? 기억력과 덧붙이기를 바꿔 직접 돌려보세요.',
        'What survives and what disappears when a story is passed from person to person 40 times? Change memory and embellishment and try it yourself.'),
 lead=T('한 사람이 들은 이야기를 다음 사람에게 전하고, 그 사람이 또 다음 사람에게 전합니다. 같은 원본에서 출발한 12개의 전달 사슬이 40번 이어지면, 이야기에서 무엇이 남고 무엇이 달라질까요?',
        'One person passes on a story they heard to the next, and that person passes it on again. When 12 chains starting from the same original are retold 40 times, what survives and what changes?'),
 model=[T('이야기는 <b>모티프</b>(사건이나 세부 내용) 30개의 목록입니다. 모티프마다 "기억에 얼마나 잘 남는가"(기억용이성)가 숨어 있고, 블록이 붉을수록 잘 남는 모티프입니다. 일부 모티프는 낯설고 튀는 세부입니다.',
          'A story is a list of 30 <b>motifs</b> (events or details). Each motif hides a "how memorable is it" score (memorability), and the redder a block, the more memorable the motif. Some motifs are odd, unusual details.'),
        T('전달자는 이야기를 다시 말할 때 모티프마다 일정 확률로 기억해 냅니다. 기억용이성이 높을수록 잘 기억하고, <b>기억력</b>이 높을수록 덜 잊습니다.',
          'When retelling, each teller recalls each motif with some probability. The more memorable the motif, the better it is recalled, and the higher the <b>memory</b>, the less is forgotten.'),
        T('낯선 세부는 일정 확률(<b>관습화</b>)로 평범하고 익숙한 모티프로 바뀌고, 일정 확률(<b>덧붙이기</b>)로 새 모티프가 하나 지어 붙으며, 가끔 이웃한 두 모티프의 순서가 바뀝니다.',
          'An odd detail is replaced with some probability (<b>conventionality</b>) by a plain, familiar motif; with some probability (<b>embellishment</b>) a new motif is invented and added; and occasionally two neighboring motifs swap places.'),
        T('같은 원본에서 출발한 사슬 12개가 서로 모르게 전해집니다. 실선 테두리는 원래 이야기에 있던 모티프, 점선 테두리는 중간에 새로 생긴 모티프예요.',
          'Twelve chains starting from the same original are passed on independently of each other. A solid outline marks a motif from the original story; a dashed outline marks one invented along the way.')],
 sliders=[('memory', T('기억력', 'Memory'), 70, 100, 2, 96, T('높을수록 이야기를 덜 잊어요', 'Higher means less of the story is forgotten')),
          ('creativity', T('덧붙이기', 'Embellishment'), 0, 100, 10, 30, T('전달자가 새 이야기를 지어 붙일 확률', 'Chance a teller invents and adds a new motif')),
          ('convention', T('관습화', 'Conventionality'), 0, 100, 10, 30, T('튀는 세부를 익숙한 이야기로 바꿀 확률', 'Chance an odd detail is turned into a familiar one'))],
 reroll=T('같은 설정, 다른 전달', 'Same settings, new retellings'),
 sections=[
  dict(title=T('① 이야기가 전해지는 모습', '① The Story Being Passed On'),
       p=T('맨 위가 원본이고, 아래 12줄이 서로 다른 전달 사슬이 지금 전하고 있는 이야기입니다. 한 칸이 모티프 하나이고, 붉을수록 기억에 잘 남아요. 원래 모티프 30개는 기억에 잘 남는 순서로 왼쪽부터 늘어놓았고, 그 사슬에서 잊히거나 바뀌면 칸이 빈 점선으로 남습니다. 오른쪽 작은 칸들은 전달 중에 새로 생긴 모티프예요. 전달이 이어질수록 오른쪽부터 비어 가는지 보세요.',
           'The top row is the original, and the 12 rows below are the stories the different chains are telling right now. Each box is one motif, and the redder it is, the more memorable. The 30 original motifs are laid out from the left in order of memorability, and when a chain forgets or changes one, its box is left as an empty dotted outline. The small boxes on the right are motifs invented along the way. Watch whether the rows empty out from the right as the retellings go on.'),
       id='c-chain', rounded=True, anim=True, thumb=True, speeds=[('1.5', T('느리게', 'Slow')), ('3', T('보통', 'Normal')), ('8', T('빠르게', 'Fast'))], speed_default='3'),
  dict(title=T('② 원래 모티프는 얼마나 남을까', '② How Much of the Original Survives'),
       p=T('가로는 전달 횟수, 세로는 원본의 모티프 30개 중 아직 이야기에 남아 있는 비율입니다. 파란 굵은 선은 12개 사슬의 평균이고 옅은 선은 사슬 하나하나예요.',
           'The horizontal axis is the number of retellings, and the vertical axis is the share of the 30 original motifs still in the story. The bold blue line is the average of the 12 chains and the faint lines are the individual chains.'),
       id='c-surv'),
  dict(title=T('③ 남은 이야기는 더 기억에 남는 쪽으로', '③ The Remaining Story Becomes More Memorable'),
       p=T('붉은 선은 이야기에 남은 모티프의 평균 기억용이성이고, 회색 점선은 원래 이야기의 평균입니다. 잊히기 쉬운 모티프부터 사라지면 평균이 올라가요.',
           'The red line is the average memorability of the motifs left in the story, and the gray dashed line is the original story\'s average. As the easily forgotten motifs drop out first, the average rises.'),
       id='c-mem'),
  dict(title=T('④ 기억력을 바꾸면', '④ When Memory Changes'),
       p=T('가로는 기억력입니다. 파랑은 원래 모티프가 남은 비율, 금색은 서로 다른 두 사슬에 남은 원래 모티프가 겹치는 정도, 회색은 남은 모티프가 우연히 정해졌다면 기대되는 겹침의 근삿값이에요. 점은 3번의 실행입니다.',
           'The horizontal axis is memory. Blue is the share of original motifs that remain, gold is how much the original motifs left in two different chains overlap, and gray is an approximation of the overlap you would expect if the survivors were chosen by chance. Dots are 3 runs.'),
       id='c-sweep', note='sweep'),
 ],
 says=T('이야기는 전해질수록 공평하게 닳지 않습니다. 잊히기 쉬운 평범한 세부부터 사라지고 기억에 잘 남는 세부가 살아남아서, 남은 이야기의 평균 기억용이성이 높아집니다. 또 서로 모르게 전해진 사슬들도 같은 모티프를 남기는 경향이 있어서, 남은 모티프의 겹침이 우연일 때보다 높았습니다.',
        'Stories do not wear down evenly as they are passed on. Plain details that are easy to forget disappear first and memorable details survive, so the average memorability of the remaining story goes up. Chains passed on independently also tend to keep the same motifs, so the overlap of the remaining motifs was higher than chance.'),
 **{'not': T('사람들의 기억이 이 모델처럼 작동한다는 뜻이 아닙니다. 모티프를 한 줄로 늘어놓고 확률로 남기거나 지우는 매우 단순한 장난감 모델이고, 이야기의 의미, 맥락, 청중, 말투는 담지 못했습니다. "기억용이성"과 "튀는 세부"의 분포, 새 모티프가 만들어지는 방식은 모두 이 프로젝트의 가정입니다.',
             'It does not mean human memory works like this model. It is a very simple toy model that lines motifs up in a row and keeps or removes them with probabilities; it does not capture the meaning of a story, its context, its audience or its wording. The distribution of "memorability" and "odd details", and the way new motifs are created, are all this project\'s assumptions.')},
 theory=[
  ('root', T('Bartlett (1932), 『Remembering』(Cambridge University Press)의 "연쇄 재현" 실험에서 온 발상입니다. 영국 학자 바틀릿은 북미 원주민 설화 「유령들의 전쟁」을 사람에서 사람으로 거듭 다시 말하게 했고, 이야기가 짧아지고 낯선 세부가 익숙한 것으로 바뀐다고 보고했습니다. 다만 후속 재현 연구에서는 왜곡이 그만큼 크지 않았다는 결과도 있어 해석이 갈립니다.',
    'The idea comes from the serial-reproduction experiments in Bartlett (1932), <i>Remembering</i> (Cambridge University Press). Bartlett had people retell the Native American tale "The War of the Ghosts" again and again, and reported that it became shorter and that unfamiliar details were replaced by familiar ones. Later replications found less distortion than he described, so the interpretation is debated.')),
  ('model', T('모티프 하나가 한 번의 전달에서 살아남을 확률은 <code>p = 1 − (1 − 기억력) × (1.5 × (1 − 기억용이성) + 0.1)</code>입니다. 기억력 슬라이더는 이 식의 앞부분이고, 기억용이성이 낮은 평범한 모티프일수록 p가 낮아 먼저 사라집니다. 낯선 세부가 익숙한 모티프로 바뀌는 확률이 관습화, 새 모티프가 붙는 확률이 덧붙이기입니다.',
    'The probability that a motif survives one retelling is <code>p = 1 − (1 − memory) × (1.5 × (1 − memorability) + 0.1)</code>. The memory slider is the first part of this formula, and plain motifs with low memorability have a lower p and vanish first. The chance that an odd detail is swapped for a familiar motif is conventionality, and the chance that a new motif is added is embellishment.')),
  ('simplify', T('실제 이야기는 모티프의 목록이 아니고 의미와 맥락으로 이어져 있습니다. 이 프로젝트는 모티프 30개, 기억용이성 분포, 25%의 튀는 세부, 위의 확률식을 모두 임의로 정했고, 논문의 실험 결과를 재현한 것이 아닙니다. 실제 사람의 기억 연구가 아니라 "이런 메커니즘이 이런 결과를 낼 수 있다"는 장난감 모델입니다.',
    'Real stories are not lists of motifs but are held together by meaning and context. This project chose the 30 motifs, the memorability distribution, the 25% share of odd details and the probability formula above by its own choice, and it does not reproduce results from any experiment. It is a toy model showing that such a mechanism can produce such results, not a study of real human memory.')),
  ('check', T('이야기 전체에 대한 이론값은 없지만 손으로 확인되는 부분이 있습니다. 기억력 96%, 기억용이성 0.5인 모티프는 p = 1 − 0.04 × 0.85 = 0.966이라 40번 뒤 0.966<sup>40</sup> ≈ 0.25가 남고, 시뮬레이션의 원본 잔존율 0.25(8회 평균)와 같은 수준입니다. "우연일 때의 겹침"은 s / (2 − s)(s = 0.25면 0.14)이고 실측 사슬 간 겹침은 0.31로 약 2배였습니다.',
    'There is no closed-form value for the whole story, but a part can be checked by hand. A motif with memorability 0.5 at memory 96% has p = 1 − 0.04 × 0.85 = 0.966, so after 40 retellings 0.966<sup>40</sup> ≈ 0.25 remains, about the simulated original-motif survival of 0.25 (8-run average). The overlap expected by chance is s / (2 − s) (0.14 at s = 0.25), and the measured overlap between chains was 0.31, about twice that.')),
  ('read', T('Bartlett (1932), 『Remembering』, Cambridge University Press. Kirby, Cornish &amp; Smith (2008), "Cumulative cultural evolution in the laboratory", <i>PNAS</i>. Norenzayan 외 (2006), "Memory and mystery: the cultural selection of minimally counterintuitive narratives", <i>Cognitive Science</i>.',
    'Bartlett (1932), <i>Remembering</i>, Cambridge University Press. Kirby, Cornish &amp; Smith (2008), "Cumulative cultural evolution in the laboratory", <i>PNAS</i>. Norenzayan et al. (2006), "Memory and mystery: the cultural selection of minimally counterintuitive narratives", <i>Cognitive Science</i>.')),
 ],
 memo=[T('모티프는 30개, 사슬은 12개, 전달은 40번입니다. 모티프를 기억해 낼 확률은 1 − (1 − 기억력) × (1.5 × (1 − 기억용이성) + 0.1)이고, 기억해 낸 모티프가 3개 미만이면 가장 기억에 남는 3개를 유지합니다. 기억용이성은 30%가 0.7~1.0(생생), 70%가 0.15~0.6(평범)이며 25%는 튀는 세부입니다.',
          'There are 30 motifs, 12 chains and 40 retellings. The probability of recalling a motif is 1 − (1 − memory) × (1.5 × (1 − memorability) + 0.1), and if fewer than 3 motifs are recalled, the 3 most memorable are kept. Memorability is 0.7 to 1.0 (vivid) for 30% of motifs and 0.15 to 0.6 (plain) for 70%, and 25% are odd details.'),
        T('기본 설정(기억력 96%, 덧붙이기 30%, 관습화 30%)에서 40번 전달한 뒤 8회 평균은 원래 모티프 25%가 남았고, 이야기 길이는 평균 15.7(처음 30), 평균 기억용이성은 0.56에서 0.62가 됐습니다. 사슬 사이 겹침은 0.31로 우연 기준 근삿값 0.14의 두 배 남짓이었습니다.',
          'With the default settings (memory 96%, embellishment 30%, conventionality 30%), the 8-run average after 40 retellings was 25% of the original motifs remaining, an average story length of 15.7 (starting at 30), and an average memorability that went from 0.56 to 0.62. The overlap between chains was 0.31, a little more than twice the chance approximation of 0.14.'),
        T('기억력을 100%로 해도 원래 모티프가 75%만 남습니다. 낯선 세부는 관습화 때문에 바뀌기 때문이에요. 덧붙이기는 남은 원래 모티프의 비율(24~25%)은 거의 바꾸지 못하고 이야기 길이만 늘립니다(원본 비중은 덧붙이기 0%에서 80%, 100%에서 22%). 관습화를 0%에서 30% 이상으로 올리면 원래 모티프가 32%에서 25%로 줄었습니다.',
          'Even with memory at 100%, only 75% of the original motifs remain, because odd details are changed by conventionality. Embellishment barely changes the share of original motifs that remain (24 to 25%) and mainly lengthens the story (the original\'s share of the story is 80% at 0% embellishment and 22% at 100%). Raising conventionality from 0% to 30% or more cut the original motifs from 32% to 25%.'),
        T('"우연일 때 기대되는 겹침"은 두 사슬이 각각 남은 비율 s만큼의 모티프를 독립적으로 무작위로 남길 때의 자카드 유사도 근삿값 s / (2 − s)입니다. ④번 그래프는 기억력마다 3번씩 돌린 결과이고, 검증은 <code>node tools/validate-telephone.js</code>로 할 수 있습니다.',
          'The "overlap expected by chance" is the approximate Jaccard similarity s / (2 − s) when two chains each independently keep a random fraction s of the motifs. Graph ④ is based on 3 runs for each memory level, and you can verify with <code>node tools/validate-telephone.js</code>.')],
))
